(
  fields: TableFieldDefinition[],
): Record<string, TableFieldDefinition[]> => {
  return fields.reduce(
    (acc, f): Record<string, TableFieldDefinition[]> => {
      if (!f.group?.name) {
        return acc;
      }

      const key = f.group.name;
      if (!acc[key]) {
        acc[key] = [];
      }

      // Strip group information from the field when adding to the fields array
      const { group, ...fieldWithoutGroup } = f;
      acc[key].push(fieldWithoutGroup);
      return acc;
    },
    {} as Record<string, TableFieldDefinition[]>,
  );
}

(fields: TableFieldDefinition[]): ProcessedTableFieldDefinition[] => {
  const seenGroup = new Set<string>();
  const groupFields = collectGroupFields(fields);
  const result: ProcessedTableFieldDefinition[] = [];

  fields.forEach((f) => {
    if (!f.group?.name) {
      result.push(f);
      return;
    }

    const key = f.group.name;
    if (seenGroup.has(key)) {
      return;
    }

    seenGroup.add(key);

    const grouped: ProcessedTableFieldDefinition = {
      ...f,
      group: {
        ...f.group,
        fields: groupFields[key],
      },
    };

    result.push(grouped);
  });

  return result;
}

(rule: CssRule, resourceValue: string): boolean => {
  const parsedResouceValue = parseStringValue(resourceValue);
  const parsedConditionValue = parseStringValue(rule.if.value);

  switch (rule.if.condition) {
    case 'equals':
      return parsedResouceValue === parsedConditionValue;
    case 'notEquals':
      return parsedResouceValue !== parsedConditionValue;
    case 'greaterThan':
      return parsedResouceValue > parsedConditionValue;
    case 'greaterThanOrEqual':
      return parsedResouceValue >= parsedConditionValue;
    case 'lessThan':
      return parsedResouceValue < parsedConditionValue;
    case 'lessThanOrEqual':
      return parsedResouceValue <= parsedConditionValue;
    case 'contains':
      if (Array.isArray(parsedResouceValue)) {
        return parsedResouceValue.includes(parsedConditionValue);
      } else if (
        typeof parsedResouceValue === 'string' &&
        typeof parsedConditionValue === 'string'
      ) {
        return parsedResouceValue.includes(parsedConditionValue);
      }

      return false;
  }
  return false;
}

(base64: string): string => {
  try {
