    const bytes = Uint8Array.from(binaryString, (char) => char.charCodeAt(0));
    return new TextDecoder().decode(bytes);
  } catch (error) {
    console.error('Base64 decoding failed:', error);
    throw new Error('Failed to decode Base64 string');
  }
}

