(
  fields: TableFieldDefinition[],
): Record<string, TableFieldDefinition[]> => {
  return fields.reduce(
    (acc, f): Record<string, TableFieldDefinition[]> => {
      if (!f.group?.name) {
        return acc;
      }

      const key = f.group.name;
      if (!acc[key]) {
        acc[key] = [];
      }

      // Strip group information from the field when adding to the fields array
      const { group, ...fieldWithoutGroup } = f;
      acc[key].push(fieldWithoutGroup);
      return acc;
    },
    {} as Record<string, TableFieldDefinition[]>,
  );
}

(fields: TableFieldDefinition[]): ProcessedTableFieldDefinition[] => {
  const seenGroup = new Set<string>();
  const groupFields = collectGroupFields(fields);
  const result: ProcessedTableFieldDefinition[] = [];

  fields.forEach((f) => {
    if (!f.group?.name) {
      result.push(f);
      return;
    }

    const key = f.group.name;
    if (seenGroup.has(key)) {
      return;
    }

    seenGroup.add(key);

    const grouped: ProcessedTableFieldDefinition = {
      ...f,
      group: {
        ...f.group,
        fields: groupFields[key],
      },
    };

    result.push(grouped);
  });

  return result;
}

(rule: CssRule, resourceValue: string): boolean => {
  const parsedResouceValue = parseStringValue(resourceValue);
  const parsedConditionValue = parseStringValue(rule.if.value);

  switch (rule.if.condition) {
    case 'equals':
      return parsedResouceValue === parsedConditionValue;
    case 'notEquals':
      return parsedResouceValue !== parsedConditionValue;
    case 'greaterThan':
      return parsedResouceValue > parsedConditionValue;
    case 'greaterThanOrEqual':
      return parsedResouceValue >= parsedConditionValue;
    case 'lessThan':
      return parsedResouceValue < parsedConditionValue;
    case 'lessThanOrEqual':
      return parsedResouceValue <= parsedConditionValue;
    case 'contains':
      if (Array.isArray(parsedResouceValue)) {
        return parsedResouceValue.includes(parsedConditionValue);
      } else if (
        typeof parsedResouceValue === 'string' &&
        typeof parsedConditionValue === 'string'
      ) {
        return parsedResouceValue.includes(parsedConditionValue);
      }

      return false;
  }
  return false;
}

(
  value: string,
  rules?: CssRule[],
): Partial<CSSStyleDeclaration> => {
  if (!rules) {
    return {};
  }

  return rules.reduce((acc, rule) => {
    const result = cssRuleResolver(rule, value);
    if (result) {
      return { ...acc, ...rule.styles };
    }
    return acc;
  }, {});
}

(value: string) => {
  if (value === 'true') {
    return true;
  }

  if (value === 'false') {
    return false;
  }

  if (!isNaN(Number(value))) {
    return Number(value);
  }

  return value;
}

(base64: string): string => {
  try {
    const binaryString = atob(base64);
    const bytes = Uint8Array.from(binaryString, (char) => char.charCodeAt(0));
    return new TextDecoder().decode(bytes);
  } catch (error) {
    console.error('Base64 decoding failed:', error);
    throw new Error('Failed to decode Base64 string');
  }
}

(str: string): string => {
  try {
    const utf8Bytes = new TextEncoder().encode(str);
    const binaryString = Array.from(utf8Bytes, (byte) => String.fromCharCode(byte)).join('');
    return btoa(binaryString);
  } catch (error) {
    console.error('Base64 encoding failed:', error);
    throw new Error('Failed to encode string to Base64');
  }
}

(
  value: string | undefined,
  transform: TransformType[] | undefined,
): string | undefined => {
  if (value == null || transform == null || !transform.length) return value;

  return transform.reduce((acc, t) => {
    if (acc == null) return acc;

    switch (t) {
      case 'uppercase':
        return acc.toUpperCase();
      case 'lowercase':
        return acc.toLowerCase();
      case 'capitalize': {
        const str = String(acc);
        return str.length ? str.charAt(0).toUpperCase() + str.slice(1) : str;
      }
      case 'decode': {
        try {
          return decodeBase64(acc);
        } catch {
          return acc;
        }
      }
      case 'encode': {
        try {
          return encodeBase64(acc);
        } catch {
          return acc;
        }
      }
      default:
        return acc;
    }
  }, value);
}
